//! PPB
//! TEAL registers accessible through the debug interface

#![allow(dead_code)]

pub const BASE: u32 = 0xe0000000;

/// ITM_STIM0 Register
///
/// Provides the interface for generating Instrumentation packets
///
/// Address offset: 0x0000
/// Reset value: 0x00000000
///
/// ## Fields
///
/// - **STIMULUS** `[31:0]` (RW)
///
///   Data to write to the Stimulus Port FIFO, for forwarding as an Instrumentation packet. The size of write access determines the type of Instrumentation packet generated.
#[repr(transparent)]
pub struct ItmStim0 {
    value: crate::common::VolatileCell<u32>,
}

impl core::ops::Deref for ItmStim0 {
    type Target = crate::common::VolatileCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl ItmStim0 {
    // ======== Field Constants ========

    /// **STIMULUS**
    ///
    /// Data to write to the Stimulus Port FIFO, for forwarding as an Instrumentation packet. The size of write access determines the type of Instrumentation packet generated.
    ///
    /// Bits `[31:0]`, mask `0xffffffff`
    pub const STIMULUS_OFFSET: u32 = 0;
    pub const STIMULUS_MASK: u32 = 0xffffffff;

    // ======== Field Accessors ========

    /// **STIMULUS** `[31:0]` (RW)
    ///
    /// Data to write to the Stimulus Port FIFO, for forwarding as an Instrumentation packet. The size of write access determines the type of Instrumentation packet generated.
    #[inline(always)]
    pub fn stimulus(&self) -> u32 {
        (self.value.read_bits() & Self::STIMULUS_MASK) >> Self::STIMULUS_OFFSET
    }

    /// Write **STIMULUS** `[31:0]` (RW)
    ///
    /// Data to write to the Stimulus Port FIFO, for forwarding as an Instrumentation packet. The size of write access determines the type of Instrumentation packet generated.
    #[inline(always)]
    pub fn write_stimulus(&self, value: u32) {
        self.value.modify_bits(|r| (r & !Self::STIMULUS_MASK) | ((value << Self::STIMULUS_OFFSET) & Self::STIMULUS_MASK));
    }

}

