    ///
    /// Bits `[26:26]`, mask `0x04000000`
    pub const S_RESTART_ST_OFFSET: u32 = 26;
    pub const S_RESTART_ST_MASK: u32 = 0x04000000;
    pub const S_RESTART_ST: u32 = 1 << 26;

