/// DCRSR Register
///
/// With the DCRDR, provides debug access to the general-purpose registers, special-purpose registers, and the FP extension registers. A write to the DCRSR specifies the register to transfer, whether the transfer is a read or write, and starts the transfer
///
/// Address offset: 0xedf4
/// Reset value: 0x00000000
///
/// ## Fields
///
/// - **REGWNR** `[16]` (RW)
///
///   Specifies the access type for the transfer
///
/// - **REGSEL** `[6:0]` (RW)
///
///   Specifies the general-purpose register, special-purpose register, or FP register to transfer
#[repr(transparent)]
pub struct Dcrsr {
    value: crate::common::VolatileCell<u32>,
}

impl core::ops::Deref for Dcrsr {
    type Target = crate::common::VolatileCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl Dcrsr {
    // ======== Field Constants ========

    /// **REGWNR**
    ///
    /// Specifies the access type for the transfer
    ///
    /// Bits `[16:16]`, mask `0x00010000`
    pub const REGWNR_OFFSET: u32 = 16;
    pub const REGWNR_MASK: u32 = 0x00010000;
    pub const REGWNR: u32 = 1 << 16;

    /// **REGSEL**
    ///
    /// Specifies the general-purpose register, special-purpose register, or FP register to transfer
    ///
    /// Bits `[6:0]`, mask `0x0000007f`
    pub const REGSEL_OFFSET: u32 = 0;
    pub const REGSEL_MASK: u32 = 0x0000007f;

    // ======== Field Accessors ========

    /// **REGWNR** `[16]` (RW)
    ///
    /// Specifies the access type for the transfer
    #[inline(always)]
    pub fn regwnr(&self) -> bool {
        (self.value.read_bits() & Self::REGWNR_MASK) != 0
    }

    /// Set REGWNR bit (RW) - NOT atomic
    #[inline(always)]
    pub fn set_regwnr(&self) {
        self.value.modify_bits(|r| r | Self::REGWNR_MASK);
    }

    /// Clear REGWNR bit (RW) - NOT atomic
    #[inline(always)]
    pub fn clr_regwnr(&self) {
        self.value.modify_bits(|r| r & !Self::REGWNR_MASK);
    }

    /// **REGSEL** `[6:0]` (RW)
    ///
    /// Specifies the general-purpose register, special-purpose register, or FP register to transfer
    #[inline(always)]
    pub fn regsel(&self) -> u32 {
        (self.value.read_bits() & Self::REGSEL_MASK) >> Self::REGSEL_OFFSET
    }

    /// Write **REGSEL** `[6:0]` (RW)
    ///
    /// Specifies the general-purpose register, special-purpose register, or FP register to transfer
    #[inline(always)]
    pub fn write_regsel(&self, value: u32) {
        self.value.modify_bits(|r| (r & !Self::REGSEL_MASK) | ((value << Self::REGSEL_OFFSET) & Self::REGSEL_MASK));
    }

}

